export interface Nav {
  pickDirectory(): Promise<string | null>
  pathFor(file: File): string
  /** @returns 打开的工作区 id（侧栏移除旧位置时排除它，1612 复核 P1）。 */
  openCaseWorkspace(root: string): Promise<string | void>
  openTab(kind: string, params?: Record<string, string>): void
  /** 开好右栏的"原文查看""材料"、右栏保持收起（令 1321 D.1）。 */
  seedTabs?(): void
  goHome(): void
  refreshModels(): void
  /** 转到某个会话（成果页"在对话区查看"，T14 派修 2）。 */
  openSession(sessionId: string): void
  /** 从侧栏案件列表移除某个旧位置的登记（文件夹改名或搬走后在新位置重新打开，令 1515 第 3 条）；不删文件和会话。 */
  forgetCaseWorkspace?(root: string, except?: string): Promise<void>
  /** 在某个会话里替律师发一句（到顶提示旁的"继续"，注记 1616 第 5 条）。@returns 发出去了没有。 */
  sendMessage?(sessionId: string, text: string): Promise<boolean>
}
let nav: Nav | undefined
export const setNav = (n: Nav | undefined): void => { nav = n }
export function getNav(): Nav {
  if (!nav) throw new Error('界面还没准备好')
  return nav
}
// 会话 → 案件：会话的工作目录就是案件文件夹（Spec 1.2）。没登记过的文件夹不会自动登记（登记会建 工作区\），
// 由律师点"作为案件打开"才调 /api/case/open。
import { useEffect, type ReactNode } from 'react'
import { openCase, loadRecent } from './cases.ts'
import { Button, Empty, S } from './kit.tsx'
import { app, samePath, type CaseRef } from './state.ts'
import { useStore } from './store.ts'

export type SessionProps = {
  sessionId: string
  useSessions?: <T>(select: (s: { byId: Record<string, { cwd?: string; blank?: boolean; running?: boolean; parentId?: string; displayTitle?: string; title?: string; updatedAt?: number } | undefined> }) => T) => T
  composerBlocks?: {
    set(sessionId: string, reason: string): void
    clear(sessionId: string, reason: string): void
  }
}

let recentLoaded = false

export function useSessionCase(p: SessionProps): { root: string | undefined; caseRef: CaseRef | undefined } {
  const root = p.useSessions?.((s) => s.byId[p.sessionId]?.cwd)
  const caseRef = useStore(app, (s) => (root ? s.cases.find((c) => samePath(c.root, root)) : undefined))
  useEffect(() => { if (!recentLoaded) { recentLoaded = true; void loadRecent() } }, [])
  return { root, caseRef }
}

/** 有案件时渲染 children，否则说明原因并给出"作为案件打开"。 */
export function WithCase({ p, children }: { p: SessionProps; children: (c: CaseRef) => ReactNode }) {
  const { root, caseRef } = useSessionCase(p)
  if (caseRef) return <>{children(caseRef)}</>
  return (
    <div style={S.pane}>
      <Empty>{root ? '这个会话所在的文件夹还没作为案件打开。' : '这个会话没有对应的案件文件夹。请从左侧"案件"打开或新建案件。'}</Empty>
      {root ? <div style={{ ...S.sub, wordBreak: 'break-all' }}>{root}</div> : null}
      {root ? <div><Button variant="outline" size="sm" onClick={() => void openCase(root, null, false)}>作为案件打开</Button></div> : null}
    </div>
  )
}

