    currentRoot: GLOBAL_OTHER_CASE.root,
    dialogs: [],
  }))
})

afterEach(async () => {
  await act(async () => { root?.unmount() })
  root = undefined
  box.remove()
  setApi(undefined)
  setNav(undefined)
  app.set(initialState)
})

const settle = async () => {
  for (let i = 0; i < 20; i++) await act(async () => { await Promise.resolve() })
}

const buttonWithText = (label: string): HTMLButtonElement | undefined =>
  [...box.querySelectorAll<HTMLButtonElement>('button')].find((item) => item.textContent?.includes(label))

const citationButton = (): HTMLButtonElement | null =>
  box.querySelector<HTMLButtonElement>(`button[aria-label="${CITATION_LABEL}"]`)

function materialId(caseId: string): string {
  return `M-${caseId}`
}

function materialsFor(caseId: string): MaterialsResult {
  return {
    ok: true,
    value: {
      materials: [{
        material_id: materialId(caseId),
        name: '借款合同',
        unit: 'page',
        unit_count: 2,
        status: 'ready',
      }],
    },
  }
}

function fixture() {
  const calls: ApiCall[] = []
  const opened: OpenedTab[] = []
  let sentMessages = 0
  let firstMaterialsCase: string | undefined
  let resolveFirstMaterials!: (value: MaterialsResult) => void
  const firstMaterials = new Promise<MaterialsResult>((resolve) => { resolveFirstMaterials = resolve })

  setApi({
    tasksList: async (request: unknown) => {
      calls.push({ method: 'tasksList', request })
      const caseId = (request as { case_id: string }).case_id
      const tasks = DOCUMENTS
        .filter((document) => document.caseRef.case_id === caseId)
        .map((document) => ({
          task_id: document.taskId,
          status: 'completed',
          drafts: [{ title: document.title, version: 1, path: document.path }],
          finished_at: null,
        }))
      return { ok: true, value: { tasks } }
    },
    outputsList: async (request: unknown) => {
      calls.push({ method: 'outputsList', request })
      return { ok: true, value: { outputs: [] } }
    },
    documentRead: async (request: unknown) => {
      calls.push({ method: 'documentRead', request })
      const path = (request as { path: string }).path
      const document = DOCUMENTS.find((item) => item.path === path)
      if (!document) return { ok: false, error: { code: 'NOT_FOUND', message: '没有这份虚构文稿' } }
      return {
        ok: true,
        value: {
          task_id: document.taskId,
          title: document.title,
          version: 1,
          path,
          text: `${document.title}在当前虚构案件里的正文，引用${CITATION}。`,
        },
      }
    },
    materialsList: async (request: unknown) => {
      calls.push({ method: 'materialsList', request })
      const caseId = (request as { case_id: string }).case_id
      if (firstMaterialsCase === undefined) {
        firstMaterialsCase = caseId
        return firstMaterials
      }
      return materialsFor(caseId)
    },
    source: async (request: unknown) => {
      calls.push({ method: 'source', request })
      return {
        ok: true,
        value: {
          name: '借款合同',
          loc: { unit: 'page', from: 1 },
          text: '借款合同第一页的虚构正文。',
          page_png_base64: null,
          source_changed: false,
        },
      }
    },
    documentsSave: async (request: unknown) => {
      calls.push({ method: 'documentsSave', request })
      return { ok: false, error: { code: 'UNEXPECTED_SAVE', message: '本用例不应保存' } }
    },
  } as unknown as LawbenchApi)

  setNav({
    openTab: (kind: string, params?: Record<string, string>) => {
      opened.push({ kind, params })
    },
    sendMessage: async () => {
      sentMessages++
      return true
    },
  } as unknown as Nav)

  return {
    calls,
    opened,
    sentMessages: () => sentMessages,
    resolveFirstMaterials: () => {
      if (firstMaterialsCase === undefined) throw new Error('materialsList 尚未被调用')
      resolveFirstMaterials(materialsFor(firstMaterialsCase))
    },
  }
}

async function renderDocuments(caseRef: CaseRef) {
  root = createRoot(box)
  await act(async () => {
    root!.render(createElement(Documents, { caseRef, sessionId: SESSION }))
  })
  await settle()
}

async function rerenderDocuments(caseRef: CaseRef) {
  await act(async () => {
    root!.render(createElement(Documents, { caseRef, sessionId: SESSION }))
  })
  await settle()
}

async function chooseDocument(title: string) {
  const choice = buttonWithText(`${title} · 第 1 版`)
  expect(choice).toBeInstanceOf(HTMLButtonElement)
  await act(async () => { choice!.click() })
  await settle()
}

async function clickCitation() {
  const mark = citationButton()
  expect(mark).toBeInstanceOf(HTMLButtonElement)
  expect(mark?.textContent).toBe(CITATION_TEXT)
  await act(async () => { mark!.click() })
  await settle()
}

function materialCalls(calls: ApiCall[]): ApiCall[] {
  return calls.filter((call) => call.method === 'materialsList')
}

function expectNoStaleEffects(svc: ReturnType<typeof fixture>): void {
  expect(svc.opened).toEqual([])
  expect(app.get().dialogs).toEqual([])
  expect(svc.sentMessages()).toBe(0)
  expect(svc.calls.some((call) => call.method === 'documentsSave')).toBe(false)
  expect(svc.calls.some((call) => call.method === 'source')).toBe(false)
}

describe('T32 文稿出处材料列表迟到回调', () => {
  it('等待甲稿材料时切到乙稿，甲稿迟到结果不打开；乙稿正控仍带乙任务和本案', async () => {
    const svc = fixture()
    await renderDocuments(CASE_A)

    expect(box.textContent).toContain('甲稿 · 第 1 版')
    expect(box.textContent).toContain('乙稿 · 第 1 版')
    await chooseDocument('甲稿')
    expect(box.textContent).toContain('甲稿在当前虚构案件里的正文')
    await clickCitation()

    expect(materialCalls(svc.calls)).toEqual([{
      method: 'materialsList',
      request: { case_id: CASE_A.case_id },
    }])

    await chooseDocument('乙稿')
    expect(box.textContent).toContain('乙稿在当前虚构案件里的正文')

    await act(async () => {
      svc.resolveFirstMaterials()
      await Promise.resolve()
    })
    await settle()
    expectNoStaleEffects(svc)

    await clickCitation()
    expect(materialCalls(svc.calls)).toEqual([
      { method: 'materialsList', request: { case_id: CASE_A.case_id } },
      { method: 'materialsList', request: { case_id: CASE_A.case_id } },
    ])
    expect(svc.opened).toEqual([{
      kind: TABS.source,
      params: {
        material_id: materialId(CASE_A.case_id),
        citation: CITATION,
        task_id: TASK_B,
      },
    }])
    expect(app.get().dialogs).toEqual([])
    expect(svc.sentMessages()).toBe(0)
    expect(svc.calls.some((call) => call.method === 'documentsSave')).toBe(false)
  })

  it('甲案材料迟到而真实 Documents 已换到乙案时，旧结果不打开；乙案正控仍带乙案乙任务', async () => {
    const svc = fixture()
    await renderDocuments(CASE_A)

    expect(box.textContent).toContain('甲稿 · 第 1 版')
    await chooseDocument('甲稿')
    expect(box.textContent).toContain('甲稿在当前虚构案件里的正文')
    await clickCitation()

    expect(materialCalls(svc.calls)).toEqual([{
      method: 'materialsList',
      request: { case_id: CASE_A.case_id },
    }])

    await rerenderDocuments(CASE_B)
    expect(box.textContent).toContain('换案乙稿 · 第 1 版')
    await chooseDocument('换案乙稿')
    expect(box.textContent).toContain('换案乙稿在当前虚构案件里的正文')

    await act(async () => {
      svc.resolveFirstMaterials()
      await Promise.resolve()
    })
    await settle()
    expectNoStaleEffects(svc)

    await clickCitation()
    expect(materialCalls(svc.calls)).toEqual([
      { method: 'materialsList', request: { case_id: CASE_A.case_id } },
      { method: 'materialsList', request: { case_id: CASE_B.case_id } },
    ])
    expect(svc.opened).toEqual([{
      kind: TABS.source,
      params: {
        material_id: materialId(CASE_B.case_id),
        citation: CITATION,
        task_id: TASK_CASE_B,
      },
    }])
    expect(svc.calls.some((call) => call.method === 'documentsSave')).toBe(false)
    expect(svc.calls.some((call) => call.method === 'source')).toBe(false)
    expect(svc.sentMessages()).toBe(0)
    expect(app.get().dialogs).toEqual([])
  })

  it('点击出处后卸载 Documents，迟到材料结果不产生任何可见副作用', async () => {
    const svc = fixture()
    await renderDocuments(CASE_A)

    expect(box.textContent).toContain('卸载前甲稿 · 第 1 版')
    await chooseDocument('卸载前甲稿')
    expect(box.textContent).toContain('卸载前甲稿在当前虚构案件里的正文')
    await clickCitation()

    expect(materialCalls(svc.calls)).toEqual([{
      method: 'materialsList',
      request: { case_id: CASE_A.case_id },
    }])

    await act(async () => { root?.unmount() })
    root = undefined
    expect(box.childElementCount).toBe(0)

    await act(async () => {
      svc.resolveFirstMaterials()
      await Promise.resolve()
    })
    await settle()
    expectNoStaleEffects(svc)
    expect(box.childElementCount).toBe(0)
  })
})
